Manages a project in LiteLLM. Projects sit between teams and keys in the hierarchy, allowing fine-grained budget and model access control within a team

## Example Usage

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as litellm from "@pulumi/litellm";

const research = new litellm.Team("research", {teamAlias: "research-team"});
const mlExperiments = new litellm.Project("ml_experiments", {
    teamId: research.id,
    projectAlias: "ml-experiments",
    description: "ML experimentation project",
    models: [
        "gpt-5.6",
        "claude-opus-5",
    ],
    maxBudget: 1000,
    softBudget: 800,
    budgetDuration: "30d",
    tpmLimit: 500000,
    rpmLimit: 5000,
    tags: [
        "research",
        "gpu",
    ],
    metadata: {
        cost_center: "R&D-001",
    },
});
