    credentialName: credentialName,
});
const conditionalStore: litellm.VectorStore[] = [];
optionalCred.then(optionalCred => Object.keys(optionalCred.credentialInfo).length).apply(length => {
    for (let range = 0; range < (length > 0 ? 1 : 0); range++) {
        conditionalStore.push(new litellm.VectorStore(`conditional_store-${range}`, {
            vectorStoreName: "conditional-store",
            customLlmProvider: "weaviate",
            litellmCredentialName: optionalCred.then(optionalCred => optionalCred.credentialName),
        }));
    }
});
